package de.tum.cit.aet.sorting;

import java.util.List;

public class BubbleSort implements SortStrategy {

    /**
     * Sorts books with BubbleSort.
     *
     * @param input the List of Books to be sorted
     */
    public void performSort(List<Book> input) {

        for (int i = input.size() - 1; i >= 0; i--) {
            for (int j = 0; j < i; j++) {
                if (input.get(j).compareTo(input.get(j + 1)) > 0) {
                    Book temp = input.get(j);
                    input.set(j, input.get(j + 1));
                    input.set(j + 1, temp);
                }
            }
        }

    }
}

