package de.tum.cit.aet.sorting;

import java.util.List;

public class Context {
    private SortStrategy sortAlgorithm;

    private List<Book> returnedBooks;

    public List<Book> getReturnedBooks() {
        return returnedBooks;
    }

    public void setReturnedBooks(List<Book> returnedBooks) {
        this.returnedBooks = returnedBooks;
    }

    public void setSortAlgorithm(SortStrategy sa) {
        sortAlgorithm = sa;
    }

    public SortStrategy getSortAlgorithm() {
        return sortAlgorithm;
    }

    /**
     * Runs the configured sort algorithm.
     */
    public void sort() {
        if (sortAlgorithm != null) {
            sortAlgorithm.performSort(this.returnedBooks);
        }
    }
}

